import { useState, useEffect } from "react";
import { Outlet, useParams, useLocation } from "react-router-dom";
import axios from 'axios';
import { PosterPath, DetailsDiv, Side, StyledBackLink, Line, LinkStyle } from './MovieDetails.styled.js';

const MovieDetails = () => {
  const { movieId } = useParams();
  const [movie, setMovie] = useState(null);
  const location = useLocation();
  const backToHome = location.state?.from ?? '/';

  useEffect(() => {
    const fetchMovieDetails = async () => {
        try {
            const API_KEY = 'b3fe8ad645f337f3fa9ceb8e5b164aa5';
            const url = `https://api.themoviedb.org/3/movie/${movieId}?language=en-US&api_key=${API_KEY}`;
            const response = await axios.get(url);
            setMovie(response.data);
        } catch (error) {
            console.error("Error fetching movie details:", error);
        }
    };

    fetchMovieDetails();
  }, [movieId]);

  if (!movie) {
      return <div>Loading movie details...</div>;
  }

  return (
    <>
      <StyledBackLink to={backToHome}>Go back</StyledBackLink>
      <DetailsDiv>
        <PosterPath src={`https://image.tmdb.org/t/p/w500/${movie.poster_path}`} alt={movie.title} />
        <Side>
          <h1>{movie.title}</h1>
          <p>User score: {movie.vote_average * 10}%</p>
          <h3>Overview</h3>
          <p>{movie.overview}</p>
          <h3>Genres</h3>
          <p>{movie.genres.map(genre => genre.name).join(', ')}</p>
        </Side>
      </DetailsDiv>
      <h2>Additional information</h2>
      <ul>
        <li><LinkStyle to="cast" state={{ from: backToHome }}>Cast</LinkStyle></li>
        <li><LinkStyle to="reviews" state={{ from: backToHome }}>Reviews</LinkStyle></li>
      </ul>
      <Line />
      <Outlet />
    </>
  );
};

export default MovieDetails;
